\"sub_mem_ker\".statement:
private lemma mem_moorePenroseSolutionSet_iff_sub_mem_ker (T : 𝓗 →L[ℝ] 𝓚) (y : 𝓚) {z x : 𝓗}
    (hz : z ∈ moorePenroseSolutionSet T y) :
    x ∈ moorePenroseSolutionSet T y ↔ x - z ∈ T.ker

\"map_sum\" \"LinearMap\".statement:
theorem LinearMap.sum_comp {R M M₂ M₃ : Type _} [Semiring R] [AddCommMonoid M] [AddCommMonoid M₂]
    [AddCommMonoid M₃] [Module R M] [Module R M₂] [Module R M₃] (f : M →ₗ[R] M₃) {α : Type _}
    (s : Finset α) (g : α → M₃ →ₗ[R] M₂) : (∑ a ∈ s, g a) ∘ₗ f = ∑ a ∈ s, g a ∘ₗ f

theorem LinearMap.IsBimoduleMap.sum_coe {p : Type _} {s : Finset p}
  (x : p → (IsBimoduleMaps R H₁ H₂)) :
  (∑ i ∈ s, x i : IsBimoduleMaps R H₁ H₂).1 = ∑ i ∈ s, (x i).1

